<script setup lang="ts">
import {ref} from 'vue';
import {ConfigProvider} from 'tdesign-vue-next';
import zhCN from 'tdesign-vue-next/es/locale/zh_CN';
import SkField from '../../../src/components/ui/SkField.vue';
import SkInput from '../../../src/components/ui/SkInput.vue';
import SkSelect from '../../../src/components/ui/SkSelect.vue';
import SkCheckbox from '../../../src/components/ui/SkCheckbox.vue';
import SkFieldset from '../../../src/components/ui/SkFieldset.vue';
const name=ref('小明同学'),address=ref('BOSS'),choice=ref<string|number>(0),changes=ref(0),submits=ref(0),checked=ref(false),checks=ref(0),disabled=ref(false),mounted=ref(true),hidden=ref(false),dialog=ref<HTMLDialogElement>(),compositionEvents=ref(0);
const options=[{value:0,label:'继承全局默认',description:'数字零',group:'默认'},{value:'disabled-a',label:'禁用 A',disabled:true,group:'默认'},{value:'disabled-b',label:'禁用 B',disabled:true,group:'默认'},{value:'0',label:'字符串零',description:'string-zero',group:'服务 A'},{value:'model-b',label:'模型 B',description:'api-model-b',group:'服务 A'}];
function unmountOpen(){document.querySelector<HTMLInputElement>('.sk-select input')?.click();mounted.value=false;}
function hideOpen(){document.querySelector<HTMLInputElement>('.sk-select input')?.click();hidden.value=true;}
function compose(){const trigger=document.querySelector<HTMLInputElement>('.sk-select input');if(trigger?.getAttribute('aria-expanded')!=='true')trigger?.click();let attempts=0;const send=()=>{const input=document.querySelector<HTMLInputElement>('.sk-select-search input');if(input?.getClientRects().length){compositionEvents.value++;input.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',isComposing:true,bubbles:true,cancelable:true}));}else if(attempts++<8)requestAnimationFrame(send);};requestAnimationFrame(send);}
</script>
<template><ConfigProvider :global-config="zhCN"><main class="parity-harness"><h1>公共表单回归</h1><p>合成资料，只使用真实公共控件；不访问模型或事项。</p><div class="form-grid"><SkField label="昵称"><SkInput v-model="name"/></SkField><SkField label="班班对我的称呼"><template #action><button class="text-button" type="button" @click="address=name">与昵称一致</button></template><SkInput v-model="address"/></SkField></div><form @submit.prevent="submits++"><button type="button" id="before-select">前一个控件</button><div v-if="mounted" v-show="!hidden"><SkField label="回归选择"><SkSelect v-model="choice" :options="options" searchable @change="changes++"/></SkField></div><button type="button" id="after-select">后一个控件</button><SkFieldset :disabled="disabled"><SkCheckbox v-model="checked" @change="checks++">回归复选</SkCheckbox></SkFieldset><SkCheckbox v-model="disabled">禁用复选域</SkCheckbox><button type="submit">提交表单</button></form><output id="result">{{JSON.stringify({type:typeof choice,value:choice,changes,submits,checked,checks,compositionEvents})}}</output><div class="harness-actions"><button type="button" @click="mounted=!mounted">挂载／卸载选择器</button><button type="button" @click="hidden=!hidden">显示／隐藏选择器</button><button type="button" @click="unmountOpen">打开后立即卸载</button><button type="button" @click="hideOpen">打开后立即隐藏</button><button type="button" @click="compose">合成 Enter</button><button type="button" @click="dialog?.showModal()">打开弹窗夹具</button></div><dialog ref="dialog"><h2>弹窗选择</h2><button type="button" @click="dialog?.close()">关闭所属弹窗</button><SkField label="弹窗模型"><SkSelect v-model="choice" :options="options" searchable/></SkField></dialog></main></ConfigProvider></template>
<style scoped>.parity-harness{max-width:900px;margin:40px auto;padding:24px}.parity-harness>div,.parity-harness form{margin:24px 0}.parity-harness form>*{margin-bottom:12px}button:not(.text-button){font:12px var(--font)}.harness-actions{display:flex;gap:12px;flex-wrap:wrap}output{display:block;padding:12px;background:var(--soft-ink)}dialog{width:460px;max-width:90vw;border:1px solid var(--line);border-radius:12px;background:var(--ivory);color:var(--ink);padding:24px}dialog>button{margin-top:20px}</style>
